<script setup>
import {ref,reactive,computed,onMounted,onUnmounted,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import Icon from './Icon.vue';import {api} from './api.js';
import PolicyCenter from './PolicyCenter.vue';
import EvaluationDataset from './EvaluationDataset.vue';
import EvolutionVersions from './EvolutionVersions.vue';
async function restoreDefault(){if(!confirm('恢复默认版本？将切换回首次发布前保存的初始策略；保留历史版本，不调用模型，仅影响之后的新审查。'))return;await act('candidate',async()=>{try{await api('/v1/govern/policy/restore-default',{expected_generation:candidates.value.release.generation});notify('已恢复默认版本');}finally{await loadPolicy();}});}
const route=useRoute(),router=useRouter();
const nav=[['review','审查工作台','发起一次有依据的代码审查'],['runs','审查记录','每次审查，均可追溯'],['monitor','运行监控','用量、状态与验证环境'],['policy','策略中心','按角色隔离，按版本治理'],['evaluation','评测中心','先验证，再发布'],['settings','连接与设置','让每一个连接真正可用']];
const page=computed(()=>route.path.slice(1)||'review'),navPage=computed(()=>page.value==='trace'?'runs':page.value),heading=computed(()=>nav.find(x=>x[0]===navPage.value)||nav[0]);
const busy=reactive({}),toast=ref(null),error=ref(''),connected=ref(false),settings=ref(null),runs=ref([]),repository=ref(null),requirements=ref([]),task=ref(null),progress=ref(null),activeId=ref(localStorage.getItem('govern-run')||''),policy=ref(null),candidates=ref(null),expanded=ref({}),priority=ref(''),search=ref(''),login=ref(false),loginForm=reactive({username:'',password:''});
const form=reactive({source:'local',path:localStorage.getItem('govern-repo')||'',url:'',mode:'working-tree',base:'main',head:'HEAD',paths:[],include_untracked:false,epic:'',requirement_keys:[],business:'{}',verification:true});
const modelForm=reactive({base_url:'',model:'',api_key:''});
const githubForm=reactive({token:'',repository:''});
async function saveGithub(clear=false){if(clear&&!confirm('移除已保存的GitHub Token？'))return;await act('githubSave',async()=>{await api('/v1/govern/settings',{github:{token:githubForm.token,clear_token:clear}});githubForm.token='';await loadSettings();notify(clear?'GitHub Token已移除':'GitHub Token已保存，不会回显');});}
async function testGithub(){await act('githubTest',async()=>{const r=await api('/v1/govern/settings/test-github',{repository:githubForm.repository});notify(`可读取${r.private?'私有':'公开'}仓库 ${r.repository}；PR拉取时还会校验源码权限`);});}
const jiraForm=reactive({enabled:true,preset:'atlassian',transport:'http',url:'https://mcp.atlassian.com/v2/mcp',command:'',args:'[]',auth:'basic',email:'',api_token:'',bearer_token:'',cloud_id:'',bug_project:'',issue_type_name:'Bug',issue_type_id:'',acceptance_field:'acceptance_criteria',tools:'{}'});
const preview=ref(null),authMessage=ref(''),jiraTools=ref([]),jiraResources=ref([]),consentModal=ref(false),consent=ref(false),feedbackModal=ref(null),feedbackForm=reactive({reason:'',reason_code:'insufficient_evidence',create_bug:false}),missedModal=ref(false),missedForm=reactive({path:'',line:1,source_stage:'correctness',reason:''});
const running=computed(()=>task.value&&['PENDING','PLANNING','EXECUTING','VALIDATING'].includes(task.value.state));
const stateText=s=>({PENDING:'排队中',EXECUTING:'审查中',PLANNING:'准备中',VALIDATING:'核验中',SUCCESS:'已完成',FAILED:'执行失败',CANCELLED:'已取消'}[s]||s);
const roleText=r=>({mapper:'需求与变更映射',correctness:'正确性审查',security:'安全性审查',contract_test:'契约与测试审查',synthesizer:'结果综合',validator:'独立证据核验'}[r]||r);
const fmt=v=>v==null||v===''||(Array.isArray(v)&&!v.length)?'未提供／未验证':typeof v==='object'?JSON.stringify(v,null,2):String(v);
const date=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const shortPath=v=>(v||'').split(/[\\/]/).filter(Boolean).pop();
const filteredRuns=computed(()=>runs.value.filter(r=>(r.repository+' '+r.id).toLowerCase().includes(search.value.toLowerCase())));
const findings=computed(()=> (task.value?.report?.findings||[]).filter(f=>!priority.value||(priority.value==='pending'?!f.business_priority:f.business_priority===priority.value)));
const files=computed(()=>[...new Set([...(repository.value?.modified_files||[]),...(form.include_untracked?repository.value?.untracked_files||[]:[])])].filter(Boolean));
const summary=computed(()=>({total:runs.value.length,completed:runs.value.filter(r=>r.state==='SUCCESS').length,failed:runs.value.filter(r=>r.state==='FAILED').length,active:runs.value.filter(r=>['PENDING','EXECUTING','PLANNING','VALIDATING'].includes(r.state)).length}));
let polling=false,timer,toastTimer;
function notify(text){toast.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value=null,6000);}
async function act(key,fn){if(busy[key])return;busy[key]=true;error.value='';try{return await fn();}catch(e){error.value=e.message;if(e.status===401)login.value=true;}finally{busy[key]=false;}}
async function loadSettings(){settings.value=await api('/v1/govern/settings',undefined,20000);connected.value=true;Object.assign(modelForm,{...settings.value.model,api_key:''});const j=settings.value.jira;Object.assign(jiraForm,{...j,preset:j.configured?j.preset:'atlassian',enabled:j.configured||jiraForm.enabled,transport:j.configured?j.transport:'http',url:j.url||'https://mcp.atlassian.com/v2/mcp',args:JSON.stringify(j.args||[]),tools:JSON.stringify(j.tools||{},null,2),api_token:'',bearer_token:''});}
async function loadRuns(){runs.value=(await api('/api/tasks?limit=100')).tasks||[];}
async function loadTask(){if(!activeId.value)return;const [t,p]=await Promise.all([api('/v1/tasks/'+activeId.value),api('/v1/govern/tasks/'+activeId.value+'/progress')]);task.value=t;progress.value=p;}
async function chooseRun(id,destination='runs'){activeId.value=id;localStorage.setItem('govern-run',id);await act('task',loadTask);router.push('/'+destination);}
async function inspectRepo(more=false){await act('repo',async()=>{const requestedPath=form.path;const old=repository.value;const r=await api('/v1/govern/repository?path='+encodeURIComponent(requestedPath)+'&skip='+(more?old?.commits.length||0:0));if(form.path!==requestedPath||form.source!=='local')return;if(more&&old)r.commits=[...old.commits,...r.commits];repository.value=r;localStorage.setItem('govern-repo',form.path);if(!more)form.paths=[];notify('已读取仓库；不会切换或修改你的分支');});}
async function loadRequirements(){await act('requirements',async()=>{const r=await api('/v1/govern/requirements?epic='+encodeURIComponent(form.epic));requirements.value=r.requirements||[];form.requirement_keys=[];notify(`已读取${requirements.value.length}条需求，请勾选本次范围`);});}
const memoryConsent=ref(false);
async function startReview(){consent.value=false;memoryConsent.value=false;consentModal.value=true;}
async function previewDiff(){await act('preview',async()=>{const signature=()=>JSON.stringify([form.source,form.path,form.mode,form.base,form.head,form.include_untracked,form.paths]);const expected=signature();const value=await api('/v1/govern/preview',{path:form.path,scope:{mode:form.mode,base:form.base,head:form.head,include_untracked:form.include_untracked,paths:form.paths}});if(signature()!==expected)return;preview.value=value;notify('本地diff已解析；没有创建任务或调用模型');});}
async function confirmReview(){if(!consent.value)return;await act('review',async()=>{if(!settings.value?.model.configured)throw Error('请先配置模型并测试连接');const business=JSON.parse(form.business||'{}');consentModal.value=false;const r=await api('/v1/govern/reviews',{allow_external_model:true,allow_external_memory:memoryConsent.value,source:{kind:form.source,path:form.path,url:form.url},scope:{mode:form.mode,base:form.base,head:form.head,include_untracked:form.include_untracked,paths:form.paths},requirement_keys:form.requirement_keys,epic_key:form.epic,business_profile:business,verification_enabled:form.verification});await loadRuns();await chooseRun(r.task_id);notify('快照已冻结，审查任务已入队');});}
let policyLoadSequence=0;
async function loadPolicy(){const sequence=++policyLoadSequence;const [active,versions]=await Promise.all([api('/v1/govern/policy'),page.value==='evaluation'?api('/v1/govern/candidates'):Promise.resolve(null)]);if(sequence!==policyLoadSequence)return;policy.value=active;if(versions)candidates.value=versions;}
async function saveModel(){await act('settings',async()=>{await api('/v1/govern/settings',{model:modelForm});await loadSettings();notify('模型已保存，密钥不会回显');});}
async function testModel(){await act('modelTest',async()=>{const r=await api('/v1/govern/settings/test-model',{});notify(`模型连接成功 · ${r.model} · ${r.latency_ms}ms`);});}
async function saveJira(){await act('jiraSave',async()=>{await api('/v1/govern/settings',{jira:{...jiraForm,args:JSON.parse(jiraForm.args),tools:JSON.parse(jiraForm.tools)}});await loadSettings();notify('Jira配置已保存，请测试连接');});}
async function testJira(){await act('jiraTest',async()=>{const r=await api('/v1/govern/settings/test-jira',{});jiraTools.value=r.tools||[];jiraResources.value=r.resources||[];if(!jiraForm.cloud_id&&jiraResources.value.length===1)jiraForm.cloud_id=jiraResources.value[0].id;notify(`MCP连接成功，读取到${jiraTools.value.length}个工具`+(r.missing_tools?.length?'；部分权限不足：'+r.missing_tools.join(', '):''));});}
async function generateProposal(){await act('evolve',async()=>{const polling=setInterval(()=>loadPolicy().catch(()=>{}),2000);try{const r=await api('/v1/govern/evolve',{});notify(r.candidates?.length?`策略提案 V${r.batch?.version} 已创建，尚未发布`:r.reason||'本次无可用候选');}finally{clearInterval(polling);await loadPolicy();}});}
async function candidateAction(c,action){const label=action==='evaluate'?'运行Validation和Holdout评测（会调用模型并可能产生费用）':action==='publish'?'确认发布此版本':'回滚至此版本';if(!confirm(label+'？'+(action==='evaluate'?'本次只评测，不自动发布。':'将切换完整策略包，仅影响之后的新审查。')))return;await act('candidate',async()=>{let current=c;const send=async(a)=>{current=await api('/v1/govern/candidates/'+current.id+'/'+a,{expected_revision:current.revision,expected_generation:candidates.value.release.generation,reason:'用户在版本页面确认：'+label});};try{if(action==='publish'){if(current.status==='HOLDOUT_PASSED')await send('approve');if(current.status!=='HUMAN_APPROVED')throw Error('请先完成Validation和Holdout评测');await send('activate');}else await send(action);}finally{await loadPolicy();}notify(action==='evaluate'?'评测已完成，请查看结果后人工确认发布':action==='publish'?'此版本已发布':'已回滚至此版本');});}
function openFeedback(f,type){feedbackModal.value={finding:f,type};Object.assign(feedbackForm,{reason:'',reason_code:type==='accepted'?'confirmed':'insufficient_evidence',create_bug:false});}
async function submitFeedback(){await act('feedback',async()=>{await api(`/v1/govern/tasks/${activeId.value}/feedback`,{finding_id:feedbackModal.value.finding.finding_id,type:feedbackModal.value.type,...feedbackForm}).then(r=>notify(r.bug_error?'反馈已保存，建Bug失败：'+r.bug_error:'反馈已保存'+(r.bug?'，Bug已创建或复用':'')));feedbackModal.value=null;await loadTask();});}
async function submitMissed(){await act('missed',async()=>{await api(`/v1/govern/tasks/${activeId.value}/feedback`,{type:'missed_issue',reason:missedForm.reason,reason_code:'missed_behavior',finding:{...missedForm,line:Number(missedForm.line)}});missedModal.value=false;notify('漏报已记录为用户反馈，不会直接污染固定测试集');});}
function download(){const url=URL.createObjectURL(new Blob([task.value.report.report_markdown],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`govern-${activeId.value}.md`;a.click();URL.revokeObjectURL(url);}
async function cancel(){await act('cancel',async()=>{await api('/v1/tasks/'+activeId.value+'/cancel',{});await loadTask();notify('已发出取消请求');});}
async function refresh(){await act('refresh',async()=>{await loadSettings();await loadRuns();if(activeId.value)await loadTask();if(['policy','evaluation'].includes(page.value))await loadPolicy();});}
onMounted(async()=>{await refresh();timer=setInterval(async()=>{if(polling||document.hidden)return;polling=true;try{if(activeId.value&&running.value){await loadTask();if(!running.value){await loadRuns();notify(task.value.state==='SUCCESS'?'真实审查完成，报告已保存':'任务已结束，请查看错误或限制');}}}catch(e){error.value=e.message;}finally{polling=false;}},2000);});
onUnmounted(()=>{clearInterval(timer);clearTimeout(toastTimer);});
watch(()=>route.path,()=>{error.value='';if(['policy','evaluation'].includes(page.value))act('policy',loadPolicy);if(page.value==='settings')act('settingsLoad',loadSettings);if(page.value==='monitor')act('history',loadRuns);});
watch(()=>form.source,()=>{repository.value=null;form.paths=[];preview.value=null;});watch(()=>form.epic,()=>{requirements.value=[];form.requirement_keys=[];});watch(()=>form.path,()=>{repository.value=null;form.paths=[];preview.value=null;});
watch(()=>[form.mode,form.base,form.head,form.include_untracked,form.paths.join('|')],()=>preview.value=null);
const metrics=computed(()=>task.value?.report?.execution||{});
</script>

<template>
 <div class="shell">
  <aside class="sidebar"><RouterLink to="/review" class="brand"><span class="brand-mark"><Icon name="shield" :size="24"/></span><span>govern<span class="brand-dot">.</span><small>AGENT HARNESS</small></span></RouterLink><div class="nav-label">工作空间</div><nav><RouterLink v-for="n in nav" :key="n[0]" :to="'/'+n[0]" :class="{active:navPage===n[0]}"><Icon :name="n[0]"/><span>{{n[1]}}</span><i v-if="n[0]==='runs'&&summary.active" class="nav-count">{{summary.active}}</i></RouterLink></nav><div class="sidebar-bottom"><div class="local-label"><span class="dot" :class="connected?'green':'red'"></span>{{connected?'本地服务已连接':'后端未连接'}}</div><small>本地Git · 证据驱动 · 可追溯</small></div></aside>
  <div class="workspace"><header class="topbar"><span class="breadcrumb">Workspace <span>/</span> {{heading[1]}}</span><div class="top-actions"><span class="pill" :class="settings?.model.configured?'success':'warning'"><span class="dot"></span>{{settings?.model.configured?settings.model.model:'模型未配置'}}</span><button class="icon-button" title="刷新连接和数据" @click="refresh" :disabled="busy.refresh"><Icon name="refresh" :class="{spin:busy.refresh}"/></button><span class="avatar">G</span></div></header>
   <main><div class="page-heading"><div><p class="eyebrow">{{page==='review'?'REVIEW WORKSPACE':'GOVERN AGENT'}}</p><h1>{{heading[1]}}</h1><p class="muted">{{heading[2]}}</p></div><button v-if="page!=='review'&&page!=='settings'" class="button primary" @click="router.push('/review')"><Icon name="plus"/> 新建审查</button><span v-else-if="page==='review'" class="local-badge"><Icon name="shield" :size="16"/> 不修改目标仓库</span></div>
    <div v-if="error" class="notice danger" role="alert"><Icon name="alert"/><span>{{error}}</span><button @click="error=''" class="icon-button"><Icon name="close" :size="16"/></button></div>
    <div v-if="!settings&&busy.refresh" class="card empty"><span class="spinner"></span><h2>正在读取本地服务配置</h2><p>正在检查模型配置、Git工具与Docker状态，不会调用模型或发送仓库代码。</p></div>
    <div v-else-if="!connected&&!busy.refresh" class="empty"><Icon name="link" :size="38"/><h2>还没有连接到后端</h2><p>请运行 scripts/start_govern.py，然后重试。这里不会显示演示数据。</p><button class="button primary" @click="refresh">重新连接</button></div>

    <template v-else-if="page==='review'">
     <div v-if="!settings?.model.configured" class="notice warning"><Icon name="alert"/><span>模型尚未配置，当前不能发起真实审查。</span><RouterLink to="/settings">前往设置 →</RouterLink></div>
     <div class="review-layout"><form class="review-form" @submit.prevent="startReview">
      <section class="card"><div class="section-title"><span class="step-number">01</span><div><h2>选择代码来源</h2><p>冻结你选中的变更，审查始终基于同一份快照</p></div></div><div class="segmented"><button type="button" :class="{selected:form.source==='local'}" @click="form.source='local'"><Icon name="folder" :size="17"/>本地Git仓库</button><button type="button" :class="{selected:form.source==='github-pr'}" @click="form.source='github-pr'"><Icon name="link" :size="17"/>GitHub Pull Request</button></div>
       <template v-if="form.source==='local'"><label for="repo-path">仓库路径 <span class="required">*</span></label><div class="input-action"><input id="repo-path" v-model.trim="form.path" placeholder="D:\projects\your-repository" required @keydown.enter.prevent="inspectRepo()"/><button type="button" class="button secondary" @click="inspectRepo()" :disabled="busy.repo||!form.path"><Icon name="folder" :size="17"/>{{busy.repo?'读取中…':'读取仓库'}}</button></div><small class="hint">输入完整本地路径；读取操作不会切换分支。</small>
        <div v-if="repository" class="repo-summary"><Icon name="branch"/><strong>{{repository.branch||'Detached HEAD'}}</strong><span class="pill" :class="repository.dirty?'warning':'success'">{{repository.dirty?'有未提交变更':'工作区干净'}}</span><span class="muted">{{files.length}}个候选文件</span></div>
        <label for="scope">审查范围</label><select id="scope" v-model="form.mode"><option value="working-tree">工作区 · HEAD与当前文件比较</option><option value="staged">暂存区 · 仅已暂存的变更</option><option value="branch">分支 · merge-base到目标分支</option><option value="range">Commit范围 · 两个固定提交之间</option></select>
        <div v-if="['branch','range'].includes(form.mode)" class="two-col"><div><label for="base">{{form.mode==='branch'?'比较基线':'起始Commit'}}</label><input id="base" v-model.trim="form.base" list="git-refs" required/></div><div><label for="head">{{form.mode==='branch'?'目标分支':'结束Commit'}}</label><input id="head" v-model.trim="form.head" list="git-refs" required/></div><datalist id="git-refs"><option v-for="r in repository?.refs||[]" :key="r" :value="r"/></datalist></div>
        <label v-if="form.mode==='working-tree'" class="check-row"><input type="checkbox" v-model="form.include_untracked"/>包含未跟踪文件（不包括Git忽略的文件）</label>
        <details v-if="repository&&['staged','working-tree'].includes(form.mode)" class="file-picker"><summary>限定审查文件 <span>{{form.paths.length?`已选${form.paths.length}项`:'默认审查整个范围'}}</span></summary><p class="hint">不勾选表示全部；选中后只审查这些路径的diff，仍可按需读取依赖。</p><div class="file-list"><label v-for="f in files" :key="f" class="check-row"><input type="checkbox" :value="f" v-model="form.paths"/><code>{{f}}</code></label><p v-if="!files.length" class="hint">未发现工作区变更。请检查暂存状态或更换范围。</p></div></details>
        <details v-if="repository?.commits.length" class="commit-picker"><summary>查看提交关系 <span>{{repository.commits.length}}条</span></summary><div v-for="c in repository.commits" :key="c.sha" class="commit-row"><span class="commit-dot"></span><code>{{c.sha.slice(0,7)}}</code><span>{{c.subject}}</span><small>← {{c.parents.map(p=>p.slice(0,7)).join(', ')||'root'}}</small></div><button type="button" class="button text" @click="inspectRepo(true)" :disabled="busy.repo">加载更多提交</button></details>
       </template><template v-else><label for="pr-url">GitHub PR地址 <span class="required">*</span></label><input id="pr-url" v-model.trim="form.url" type="url" required placeholder="https://github.com/owner/repo/pull/123"/><small class="hint">手动指定PR；固定base/head SHA，不自动评论或修改PR。</small></template>
      </section>
      <section class="card"><div class="section-title"><span class="step-number">02</span><div><h2>关联产品需求 <span class="optional">可选</span></h2><p>只使用你选择的需求，不让Agent自由探索Issue</p></div></div><div v-if="!settings?.jira.configured" class="integration-empty"><span class="integration-logo">J</span><div><strong>尚未连接Jira</strong><p>连接后可读取Epic / PRD与验收条件，并将有效问题创建为Bug。</p></div><RouterLink to="/settings" class="button secondary">配置连接 <Icon name="arrow" :size="16"/></RouterLink></div><template v-else><label for="epic">Epic / PRD Issue Key</label><div class="input-action"><input id="epic" v-model.trim="form.epic" placeholder="例如 PAY-100"/><button type="button" class="button secondary" @click="loadRequirements" :disabled="busy.requirements||!form.epic">{{busy.requirements?'正在读取…':'获取关联需求'}}</button></div><div class="requirements-list" v-if="requirements.length"><details v-for="r in requirements" :key="r.requirement_id"><summary><label @click.stop><input type="checkbox" :value="r.requirement_id" v-model="form.requirement_keys"/> <b>{{r.requirement_id}}</b> {{r.title}}</label></summary><pre>{{r.description}}</pre><p v-for="a in r.acceptance_criteria" :key="a.criterion_id"><code>{{a.criterion_id}}</code> {{a.text}}</p><small v-for="l in r.limitations" :key="l" class="hint">{{l}}</small></details></div></template><div class="inline-note"><Icon name="shield" :size="16"/>未关联需求时仍审查正确性、安全与契约；PRD业务一致性将标记为“未验证”。</div><details><summary>补充仓库业务画像</summary><label for="business">核心链路、关键数据、模块约定（JSON）</label><textarea id="business" v-model="form.business" rows="5" spellcheck="false" placeholder='{"core_flows":["支付"],"modules":["src/payments"]}'/></details></section>
      <section class="card"><div class="section-title"><span class="step-number">03</span><div><h2>验证与执行</h2><p>静态证据核验始终开启，运行验证由Validator按需发起</p></div></div><label class="switch-row"><div><strong>允许沙箱运行验证</strong><p>生成最小复现与外部mock，在隔离快照中执行测试</p></div><input type="checkbox" v-model="form.verification"/></label><div class="inline-note" :class="{'warning-text':!settings?.runtime.docker_available}"><span class="dot" :class="settings?.runtime.docker_available?'green':'amber'"></span>{{settings?.runtime.docker_available?'Docker Linux引擎可用':'Docker不可用：保留静态审查，不回退宿主执行'}} · {{Object.keys(settings?.runtime.profiles||{}).join('、')||'未配置执行Profile'}}</div></section>
      <section v-if="preview" class="card"><h2>本地变更预览</h2><p class="hint">{{preview.changed_paths.length}}个文件 · {{preview.change_units}}个ChangeUnit · 不创建任务，不调用模型</p><p class="hint">真正提交审查时会重新冻结，避免使用过期预览。</p><details><summary>查看diff与冻结标识</summary><pre>{{preview.diff}}</pre><code>SHA-256: {{preview.diff_sha256}}</code><p class="hint" v-if="preview.truncated">预览内容已截断，Hash基于完整diff。</p></details></section>
      <div class="submit-bar"><span><Icon name="shield" :size="16"/>审查将消耗 Token</span><div class="row"><button v-if="form.source==='local'" class="button secondary" type="button" @click="previewDiff" :disabled="busy.preview||!form.path">{{busy.preview?'本地解析中…':'本地预览（不调用模型）'}}</button><button class="button primary large" type="submit" :disabled="busy.review||!settings?.model.configured"><Icon :name="busy.review?'refresh':'arrow'" :class="{spin:busy.review}"/>{{busy.review?'正在冻结并提交…':'冻结并开始审查'}}</button></div></div>
     </form><aside class="review-aside"><section class="card flow-card"><p class="eyebrow">HOW IT WORKS</p><h2>每一步，都有证据</h2><ol><li v-for="[title,text] in [['冻结输入','Git变更、需求、策略与模型配置'],['需求变更映射','构建Unit并映射选中的验收条件'],['三个领域并行审查','正确性 / 安全性 / 契约与测试'],['综合与独立核验','去重、静态核验与按需运行验证'],['沉淀报告与反馈','结构化结果，人工确认后治理']]" :key="title"><span></span><div><strong>{{title}}</strong><p>{{text}}</p></div></li></ol><div class="flow-footer"><Icon name="trace"/><span>审查开始后，可实时查看阶段与工具活动。</span></div></section><section class="card compact"><h3>运行环境</h3><div class="environment-row"><span>模型</span><strong>{{settings?.model.configured?'已配置':'未配置'}}</strong></div><div class="environment-row"><span>代码检索</span><strong>{{settings?.runtime.ripgrep?'Ripgrep':'Python降级检索'}}</strong></div><div class="environment-row"><span>需求连接</span><strong>{{settings?.jira.configured?'Jira MCP':'未连接'}}</strong></div><div class="environment-row"><span>存储</span><strong>{{settings?.storage.database||'—'}}</strong></div><RouterLink to="/settings" class="settings-link">管理连接与配置 →</RouterLink></section></aside></div>
    </template>

    <template v-else-if="page==='runs'||page==='trace'">
     <div class="run-layout"><section class="card run-list"><div class="list-top"><h2>审查记录 <span class="count">{{runs.length}}</span></h2><button class="icon-button" @click="act('history',loadRuns)" title="刷新列表"><Icon name="refresh" :size="17"/></button></div><input v-model="search" class="search" placeholder="搜索仓库或Run ID"/><button v-for="r in filteredRuns" :key="r.id" class="run-item" :class="{selected:activeId===r.id}" @click="chooseRun(r.id,page)"><span class="run-item-head"><strong>{{shortPath(r.repository)}}</strong><span class="status" :class="r.state">{{stateText(r.state)}}</span></span><small>{{r.id.slice(0,8)}} · {{date(r.created_at)}}</small></button><div v-if="!filteredRuns.length" class="empty small"><Icon name="runs"/><p>还没有审查记录</p></div></section>
      <section class="run-content"><div v-if="!task" class="card empty"><Icon name="runs" :size="42"/><h2>选择一次审查</h2><p>查看审查进度、问题和报告。</p><RouterLink to="/review" class="button primary">开始审查</RouterLink></div><template v-else><div class="card run-header"><div class="row between"><div><span class="status" :class="task.state">{{stateText(task.state)}}</span><h2>{{shortPath(task.repository)}}</h2><code>{{task.id}}</code></div><div class="row"><button v-if="running" class="button secondary" @click="cancel" :disabled="busy.cancel">取消任务</button><button v-if="task.report" class="button secondary" @click="download"><Icon name="download" :size="17"/>导出报告</button><button class="icon-button" @click="act('task',loadTask)" title="刷新任务"><Icon name="refresh"/></button></div></div><p class="hint">冻结快照 {{task.input?.snapshot_id}} · {{date(task.created_at)}}</p><div v-if="task.error" class="notice danger"><Icon name="alert"/><span>{{task.error}}</span></div><div v-if="running" class="running-banner"><span class="spinner"></span><div><strong>审查正在执行</strong><p>已完成 {{progress?.completed_stages||0}} / {{progress?.planned_stages||'—'}} 个阶段任务 · 执行状态自动更新</p></div></div><div class="stage-grid"><div v-for="r in ['mapper','correctness','security','contract_test','synthesizer','validator']" :key="r" :class="{done:progress?.stages?.some(s=>s.role===r&&s.state==='completed'),live:running&&progress?.stages?.some(s=>s.role===r&&s.state==='running')}" class="stage"><span>{{progress?.stages?.some(s=>s.role===r&&s.state==='completed')?'✓':'○'}}</span>{{roleText(r)}}</div></div><div class="report-tabs"><button :class="{active:page==='runs'}" @click="router.push('/runs')">审查报告</button><button :class="{active:page==='trace'}" @click="router.push('/trace')">执行轨迹 <span>{{progress?.events?.length||0}}</span></button></div></div>
       <template v-if="page==='trace'"><section class="card"><div class="section-heading"><h2>实时执行事件</h2><span class="pill">{{running?'持续更新':'持久化记录'}}</span></div><div v-if="!progress?.events?.length" class="empty small"><p>任务尚未产生Agent事件。若持续排队，请检查后端队列。</p></div><details v-for="e in progress?.events||[]" :key="e.sequence" class="trace-event"><summary><span class="event-dot"></span><code>#{{e.sequence}}</code><b>{{roleText(e.detail?.role||e.role)}}</b><span>{{e.detail?.event||e.kind}}</span><small>{{date(e.created_at)}}</small></summary><div class="trace-detail"><pre>{{fmt(e.detail)}}</pre></div></details></section></template>
       <template v-else-if="task.report"><div class="report-stats"><div v-for="p in ['P0','P1','P2']" :key="p"><span :class="p">{{p}}</span><strong>{{task.report.findings.filter(f=>f.business_priority===p).length}}</strong><small>{{p==='P0'?'严重阻断':p==='P1'?'重要风险':'一般问题'}}</small></div><div><span>Token</span><strong>{{(metrics.total_tokens||0).toLocaleString()}}</strong><small>{{metrics.cost_configured?'估算 $'+Number(metrics.cost_usd).toFixed(4):'单价未配置，不估算费用'}}</small></div></div><details class="card coverage"><summary><Icon name="shield" :size="18"/>覆盖范围与未验证限制</summary><pre>{{fmt(task.report.coverage)}}</pre></details><div class="row between findings-toolbar"><h2>审查发现 <span class="count">{{task.report.findings.length}}</span></h2><div class="row"><button class="button secondary" @click="missedModal=true">补充漏报</button><select v-model="priority"><option value="">全部风险</option><option>P0</option><option>P1</option><option>P2</option><option value="pending">待确认</option></select></div></div><div v-if="!findings.length" class="card empty"><Icon name="check" :size="38"/><h2>{{task.report.findings.length?'没有符合筛选的发现':'本次未输出已核验问题'}}</h2><p>这不代表不存在缺陷，请同时阅读覆盖范围和验证限制。</p></div><article v-for="f in findings" :key="f.finding_id" class="card finding"><div class="finding-title"><span class="risk" :class="f.business_priority||'pending'">{{f.business_priority||'待确认'}}</span><h2>{{f.title}}</h2><code>{{f.finding_id.slice(0,10)}}</code></div><div class="finding-meta"><code>{{f.path}}:{{f.line}} · {{f.side}}</code><span>{{roleText(f.source_stage)}}</span><span>{{f.severity}} / {{f.confidence??'未提供置信度'}}</span></div><dl><template v-for="[k,v] in [['风险等级',`${f.business_priority||'待确认'} · 技术严重性 ${f.severity}`],['来源模块',f.source_module],['关联测试用例',f.related_tests],['风险位置',`${f.path}:${f.line} (${f.side})`],['问题描述',f.description],['影响范围',f.impact_scope],['修复建议',f.recommendation],['证据依据',f.evidence_refs]]" :key="k"><dt>{{k}}</dt><dd><pre v-if="typeof v==='object'">{{fmt(v)}}</pre><span v-else>{{fmt(v)}}</span></dd></template></dl><details class="verification"><summary>运行验证 · {{f.runtime_verdict||'not_applicable'}}</summary><pre>{{fmt({static_verdict:f.static_verdict,runtime_verdict:f.runtime_verdict,verification_refs:f.verification_refs,limitations:f.limitations})}}</pre></details><div class="finding-actions"><button class="button secondary" @click="openFeedback(f,'accepted')"><Icon name="check" :size="16"/>问题有效</button><button class="button text" @click="openFeedback(f,'false_positive')"><Icon name="close" :size="16"/>置为无效</button></div></article></template><section v-else class="card empty"><Icon name="clock" :size="38"/><h2>{{running?'审查执行中，报告尚未生成':'尚无审查报告'}}</h2><p>{{running?'切换执行轨迹查看实时模型与工具活动。':'执行失败不会生成伪造的空报告；请检查错误详情。'}}</p><button class="button secondary" @click="router.push('/trace')">查看执行轨迹</button></section>
       <details v-if="page==='runs'&&task.report?.filtered_findings?.length" class="card coverage"><summary>已排除记录 · {{task.report.filtered_findings.length}} 条（不计入问题数）</summary><p class="muted">已修复、无回归及证据不足的候选分别保留原因；证据不足不等于代码安全。</p><div v-for="(item,i) in task.report.filtered_findings" :key="i"><h3>{{item.title||item.finding_id}}</h3><pre>{{fmt({finding_id:item.finding_id,source_stage:item.source_stage,reason:item.reason,change_causality:item.finding?.change_causality})}}</pre></div></details>
       <details v-if="page==='runs'&&task.report?.observations?.length" class="card coverage"><summary>补充审查说明（非 Finding）</summary><pre>{{fmt(task.report.observations)}}</pre></details>
      </template></section></div>
    </template>

    <template v-else-if="page==='monitor'"><div class="metric-grid"><div class="card" v-for="[label,value] in [['已记录任务',summary.total],['完成',summary.completed],['正在执行',summary.active],['失败',summary.failed]]" :key="label"><p>{{label}}</p><strong>{{value}}</strong><small>最近100条真实任务</small></div></div><section class="card"><div class="section-heading"><h2>当前连接与能力</h2><RouterLink to="/settings">管理设置 →</RouterLink></div><div class="connection-grid"><div><Icon name="link"/><h3>模型API</h3><p>{{settings?.model.model||'未配置'}}</p><small>{{settings?.model.base_url}}</small></div><div><Icon name="shield"/><h3>运行验证</h3><p>{{settings?.runtime.docker_available?'Docker Linux可用':'Docker不可用'}}</p><small>{{Object.keys(settings?.runtime.profiles||{}).join(', ')||'无Profile'}}</small></div><div><Icon name="folder"/><h3>Jira MCP</h3><p>{{settings?.jira.configured?'已配置，需测试权限':'尚未连接'}}</p><small>读取需求 / 确认后创建Bug</small></div></div></section><section class="card"><h2>任务与用量入口</h2><p class="muted">Token、模型费用与运行验证证据保存在各任务报告和Trace；不将在线反馈当作真实Precision或Recall。</p><div v-for="r in runs" :key="r.id" class="table-row" @click="chooseRun(r.id)"><strong>{{shortPath(r.repository)}}</strong><code>{{r.id.slice(0,8)}}</code><span class="status" :class="r.state">{{stateText(r.state)}}</span><small>{{date(r.created_at)}}</small><Icon name="arrow" :size="16"/></div></section></template>
<template v-else-if="page==='policy'||page==='evaluation'"><div v-if="busy.policy" class="card empty"><span class="spinner"></span><p>正在读取实际策略与评测记录…</p></div><template v-else-if="policy"><template v-if="page==='policy'"><section class="card bundle-heading"><span class="brand-mark"><Icon name="policy"/></span><div><h2>当前生效策略 · {{policy.active_release?.is_default?'默认版本':'版本_'+date(policy.active_release?.created_at)}}</h2><small>发布代数 {{policy.active_release?.generation??0}} · 当前有效策略</small><code>{{policy.sha256}}</code></div><span class="pill success">按角色隔离</span></section><PolicyCenter :policy="policy" @saved="loadPolicy"/></template><template v-else><EvaluationDataset :dataset="candidates?.dataset"/></template><EvolutionVersions v-if="page==='evaluation'" :data="candidates" :generating="busy.evolve" :acting="busy.candidate" @refresh="act('policy',loadPolicy)" @generate="generateProposal" @restore-default="restoreDefault" @action="candidateAction"/></template><section v-else class="card empty"><p>尚未加载成功，请刷新；如无权限请登录管理员账号。</p><button class="button secondary" @click="act('policy',loadPolicy)">重新加载</button></section></template>

    <template v-else-if="page==='settings'"><div class="settings-layout"><div><section class="card"><div class="section-title"><span class="integration-logo model-logo">M</span><div><h2>模型连接</h2><p>配置代码审查使用的模型服务。</p></div><span class="pill" :class="settings?.model.configured?'success':'warning'">{{settings?.model.configured?'密钥已配置':'未配置'}}</span></div><form @submit.prevent="saveModel"><label for="model-base">API Base URL</label><input id="model-base" v-model.trim="modelForm.base_url" type="url" required placeholder="https://your-provider/v1"/><label for="model-name">模型名称</label><input id="model-name" v-model.trim="modelForm.model" required placeholder="模型ID"/><label for="model-key">API Key</label><input id="model-key" v-model="modelForm.api_key" type="password" autocomplete="new-password" :placeholder="settings?.model.key_configured?'已保存；留空保留现有密钥':'请输入API密钥'"/><small class="hint">仅发送到本机后端。不会回显或保存到浏览器缓存。</small><div class="form-footer"><button class="button primary" :disabled="busy.settings">{{busy.settings?'保存中…':'保存模型'}}</button><button type="button" class="button secondary" @click="testModel" :disabled="busy.modelTest||!settings?.model.configured">{{busy.modelTest?'连接测试中…':'测试模型连接'}}</button></div></form></section>
<section class="card"><div class="section-title"><span class="integration-logo">G</span><div><h2>GitHub只读连接</h2><p>获取PR元数据与冻结源码，不评论、不推送、不修改PR。</p></div><span class="pill" :class="settings?.github?.token_configured?'success':'warning'">{{settings?.github?.token_configured?'Token已配置':'匿名访问'}}</span></div><form @submit.prevent="saveGithub(false)"><label for="github-token">GitHub Token</label><input id="github-token" v-model="githubForm.token" type="password" autocomplete="new-password" :placeholder="settings?.github?.token_configured?'已保存；留空保留现有Token':'公开仓库可匿名；私有仓库需要只读Token'"/><small class="hint">建议使用限定目标仓库的细粒度Token：Contents与Pull requests只读。凭证仅保存在本机配置，不回显、不写入仓库或命令行。</small><div class="form-footer"><button class="button primary" :disabled="busy.githubSave">保存GitHub Token</button><button type="button" class="button secondary" :disabled="busy.githubSave||!settings?.github?.token_configured" @click="saveGithub(true)">移除Token</button></div><label for="github-repository">测试仓库</label><input id="github-repository" v-model.trim="githubForm.repository" placeholder="owner/repository"/><button type="button" class="button secondary" :disabled="busy.githubTest||!githubForm.repository" @click="testGithub">{{busy.githubTest?'检查中…':'检查仓库读取权限'}}</button></form></section>
<section class="card"><div class="section-title"><span class="integration-logo">J</span><div><h2>Jira / PRD连接</h2><p>读取选定需求，人工确认后创建Bug</p></div><span class="pill" :class="settings?.jira.configured?'success':'warning'">{{settings?.jira.configured?'配置已保存':'未连接'}}</span></div><div class="notice info"><Icon name="link"/><div>通过 Atlassian Rovo MCP 读取需求和创建问题。<a href="https://developer.atlassian.com/cloud/rovo-mcp/guides/configuring-authentication-via-api-token/" target="_blank" rel="noreferrer">查看官方认证文档 ↗</a></div></div><form @submit.prevent="saveJira"><label for="jira-preset">连接类型</label><select id="jira-preset" v-model="jiraForm.preset"><option value="atlassian">官方Atlassian Rovo MCP</option><option value="custom">自定义MCP（高级）</option></select><template v-if="jiraForm.preset==='atlassian'"><div class="inline-note">官方地址：https://mcp.atlassian.com/v2/mcp</div><label for="jira-auth">认证方式</label><select id="jira-auth" v-model="jiraForm.auth"><option value="basic">个人API Token（Email + Token）</option><option value="bearer">服务账号API Key（Bearer）</option></select><template v-if="jiraForm.auth==='basic'"><label for="jira-email">Atlassian账号Email</label><input id="jira-email" type="email" v-model.trim="jiraForm.email"/><label for="jira-token">API Token</label><input id="jira-token" type="password" v-model="jiraForm.api_token" autocomplete="new-password" :placeholder="settings?.jira.has_auth?'已保存；留空保留现有凭证':'需包含Jira read / search / write所需scope'"/></template><template v-else><label for="jira-bearer">服务账号API Key</label><input id="jira-bearer" type="password" v-model="jiraForm.bearer_token" autocomplete="new-password" placeholder="仅在本地保存，不回显"/></template><label for="cloud-id">Jira Cloud ID</label><input id="cloud-id" v-model.trim="jiraForm.cloud_id" placeholder="连接测试后从可访问站点选择／填写"/><small class="hint">组织管理员需允许API Token认证；若禁用，需要通过OAuth客户端授权后使用自定义连接。</small></template><template v-else><label>Transport</label><select v-model="jiraForm.transport"><option value="http">HTTP / Streamable HTTP</option><option value="stdio">本地stdio MCP</option></select><template v-if="jiraForm.transport==='http'"><label>MCP URL</label><input v-model.trim="jiraForm.url" type="url"/><label>Bearer Token（可选）</label><input v-model="jiraForm.bearer_token" type="password" autocomplete="new-password"/></template><template v-else><label>可执行文件路径</label><input v-model.trim="jiraForm.command" placeholder="绝对路径，例如 C:\tools\mcp-server.exe"/><label>参数（JSON数组）</label><textarea v-model="jiraForm.args" rows="3"/></template><label>操作→MCP工具映射（JSON）</label><textarea v-model="jiraForm.tools" rows="7" spellcheck="false"/></template><div class="two-col"><div><label for="bug-project">Bug项目Key</label><input id="bug-project" v-model.trim="jiraForm.bug_project" placeholder="例如 KAN"/></div><div><label>验收条件字段</label><input v-model.trim="jiraForm.acceptance_field" placeholder="acceptance_criteria 或 customfield_XXXXX"/></div></div><div class="two-col"><div><label for="bug-type-name">Bug工作类型名称</label><input id="bug-type-name" v-model.trim="jiraForm.issue_type_name" placeholder="例如 Bug 或 故障"/></div><div><label for="bug-type-id">Bug工作类型ID（可选）</label><input id="bug-type-id" v-model.trim="jiraForm.issue_type_id" placeholder="例如 10006"/></div></div><small class="hint">没有独立验收字段时，将从描述中读取 AC-…： 开头的明确验收条目，不自动猜测需求。</small><div class="form-footer"><button class="button primary" :disabled="busy.jiraSave">保存Jira连接</button><button type="button" class="button secondary" @click="testJira" :disabled="busy.jiraTest||!settings?.jira.configured">{{busy.jiraTest?'测试连接中…':'测试连接 / 获取工具'}}</button></div><div v-if="jiraTools.length" class="tool-list"><p>服务实际返回的工具</p><details v-for="t in jiraTools" :key="t.name"><summary>{{t.name}}</summary><pre>{{fmt(t)}}</pre></details></div></form></section></div>
     <aside class="review-aside"><section class="card compact"><h3>安全与配置边界</h3><ul class="help-list"><li>密钥只保存在本机被Git忽略的配置中。</li><li>运行中的任务使用冻结配置，连接配置需等任务结束后修改。</li><li>Jira仅在你选定的Epic / PRD内获取需求。</li><li>创建Bug需要在Finding反馈中单独确认，不自动创建。</li><li>未连接或权限不足会明确报错，不产生虚拟需求。</li></ul></section><section class="card compact"><h3>本地服务</h3><div class="environment-row"><span>后端</span><b>127.0.0.1:8080</b></div><div class="environment-row"><span>队列</span><b>{{settings?.storage.queue}}</b></div><p class="hint">{{settings?.storage.config_path}}</p></section></aside></div></template>
    <section v-if="page==='settings'&&jiraResources.length" class="card site-results"><h2>当前账号可访问的Atlassian站点</h2><p class="hint">选择目标站点，再点击“保存Jira连接”以固定Cloud ID。</p><div v-for="site in jiraResources" :key="site.id" class="table-row"><strong>{{site.name||site.url}}</strong><code>{{site.id}}</code><button class="button secondary" @click="jiraForm.cloud_id=site.id;notify('已选择站点，请保存Jira连接')">选择此站点</button></div></section>
    <footer class="page-footer"><span>Govern Agent Harness</span><span>证据先于结论 · 反馈先于进化</span></footer>
   </main>
  </div><Transition name="toast"><div v-if="toast" class="toast" role="status"><Icon name="check" :size="18"/>{{toast}}</div></Transition>
  <div v-if="consentModal" class="modal-backdrop" @click.self="consentModal=false"><section class="modal"><div class="section-heading"><h2>确认本次代码审查与数据外发</h2><button class="icon-button" @click="consentModal=false"><Icon name="close"/></button></div><div class="notice warning"><Icon name="alert"/><span>开始后会向上述第三方模型发送审查所需代码，可能产生费用。</span></div><dl class="consent-details"><dt>目标服务</dt><dd>{{settings?.model.base_url}}</dd><dt>模型</dt><dd>{{settings?.model.model}}</dd><dt>仓库</dt><dd>{{form.source==='local'?form.path:form.url}}</dd><dt>范围</dt><dd>{{form.mode}} · {{form.paths.length?form.paths.join(', '):'选中范围内全部变更'}}</dd></dl><p class="hint">发送选中的diff、所选需求，以及按需检索的相关源码、调用方和测试代码。不发送.env、模型密钥或宿主凭证。模型输出会记录在本地任务中。</p><label class="check-row"><input type="checkbox" v-model="consent"/>我允许本次向上述模型服务发送审查所需代码</label><label class="check-row"><input type="checkbox" v-model="memoryConsent"/>同时允许发送本仓库召回的少量历史记忆（可能包含代码、需求和反馈摘要，仅本次有效）</label><div class="form-footer"><button class="button secondary" @click="consentModal=false">暂不授权</button><button class="button primary" :disabled="!consent||busy.review" @click="confirmReview">确认并开始审查</button></div></section></div>
  <div v-if="feedbackModal" class="modal-backdrop" @click.self="feedbackModal=null"><section class="modal"><div class="section-heading"><h2>{{feedbackModal.type==='accepted'?'确认问题有效':'将问题置为无效'}}</h2><button class="icon-button" @click="feedbackModal=null"><Icon name="close"/></button></div><h3>{{feedbackModal.finding.title}}</h3><code>{{feedbackModal.finding.path}}:{{feedbackModal.finding.line}}</code><form @submit.prevent="submitFeedback"><label>反馈依据 <span class="required">*</span></label><textarea v-model.trim="feedbackForm.reason" required rows="4" placeholder="说明需求依据、上游校验或复现证据"/><template v-if="feedbackModal.type==='false_positive'"><label>原因分类</label><select v-model="feedbackForm.reason_code"><option value="insufficient_evidence">证据不足</option><option value="upstream_guard">已有上游校验</option><option value="preexisting">历史问题，非本次引入</option><option value="requirement_mismatch">需求／业务理解有误</option><option value="other">其他</option></select></template><template v-else><label class="check-row"><input type="checkbox" v-model="feedbackForm.create_bug" :disabled="!settings?.jira.configured"/>同时在Jira创建Bug {{settings?.jira.configured?'':'（请先配置Jira）'}}</label><details v-if="feedbackForm.create_bug"><summary>查看即将创建的Bug内容</summary><pre>{{fmt(feedbackModal.finding)}}</pre></details></template><div class="form-footer"><button class="button secondary" type="button" @click="feedbackModal=null">取消</button><button class="button primary" :disabled="busy.feedback">{{busy.feedback?'提交中…':'确认并保存反馈'}}</button></div></form></section></div>
  <div v-if="missedModal" class="modal-backdrop" @click.self="missedModal=false"><section class="modal"><div class="section-heading"><h2>补充漏报</h2><button class="icon-button" @click="missedModal=false"><Icon name="close"/></button></div><form @submit.prevent="submitMissed"><label>文件路径</label><input v-model.trim="missedForm.path" required/><label>行号</label><input v-model="missedForm.line" type="number" min="1" required/><label>来源领域</label><select v-model="missedForm.source_stage"><option value="correctness">正确性</option><option value="security">安全性</option><option value="contract_test">契约／测试</option><option value="mapper">需求映射</option></select><label>问题与依据</label><textarea v-model.trim="missedForm.reason" required rows="4"/><div class="form-footer"><button class="button primary" :disabled="busy.missed">保存漏报反馈</button></div></form></section></div>
  <div v-if="login" class="modal-backdrop"><section class="modal"><h2>登录本地服务</h2><form @submit.prevent="act('login',async()=>{const r=await api('/v1/auth/login',loginForm);sessionStorage.setItem('govern-token',r.access_token);login=false;await refresh()})"><label>用户名</label><input v-model="loginForm.username" autocomplete="username"/><label>密码</label><input v-model="loginForm.password" type="password" autocomplete="current-password"/><div class="form-footer"><button class="button primary" :disabled="busy.login">登录</button></div></form></section></div>
 </div>
</template>
